const body = pm.response.json();

pm.test("Responde 200 OK", function () {
    pm.response.to.have.status(200);
});

pm.test("La respuesta es una lista", function () {
    pm.expect(body).to.be.an("array");
});

pm.test("Todas las mascotas están activas", function () {
    body.forEach(pet => pm.expect(pet.status).to.eql("ACTIVE"));
});

pm.test("Cada mascota tiene nombre y especie", function () {
    body.forEach(pet => {
        pm.expect(pet.name).to.be.a("string").and.not.empty;
        pm.expect(pet.species).to.be.a("string").and.not.empty;
    });
});
